import java.util.*; class Solution { public int removeBoxes(int[] boxes) { int n = boxes.length; int[][][] memo = new int[n][n][n]; return calculate(boxes, 0, n - 1, 0, memo); } private int calculate(int[] boxes, int i, int j, int k, int[][][] memo) { if (i > j) return 0; if (memo[i][j][k] != 0) return memo[i][j][k]; int tempI = i; int tempK = k; while (tempI + 1 <= j && boxes[tempI + 1] == boxes[tempI]) { tempI++; tempK++; } int res = (tempK + 1) * (tempK + 1) + calculate(boxes, tempI + 1, j, 0, memo); for (int m = tempI + 1; m <= j; m++) { if (boxes[m] == boxes[tempI]) { res = Math.max(res, calculate(boxes, tempI + 1, m - 1, 0, memo) + calculate(boxes, m, j, tempK + 1, memo)); } } memo[i][j][k] = res; return res; } }